import { ChevronDownIcon, ChevronRightIcon } from "lucide-react"

/**
 * Child-count pill that collapses or expands a subtree. Not a tab stop: the
 * tree's arrow keys do the same job, and a click keeps focus where it was.
 */
export function CollapsePill({
  count,
  expanded,
  onToggle,
  label,
}: {
  count: number
  expanded: boolean
  onToggle: () => void
  label: string
}) {
  const Chevron = expanded ? ChevronDownIcon : ChevronRightIcon
  return (
    <button
      type="button"
      tabIndex={-1}
      aria-label={label}
      data-mini="pill"
      onMouseDown={(event) => event.preventDefault()}
      onClick={(event) => {
        event.stopPropagation()
        onToggle()
      }}
      className="mr-1.5 inline-flex h-4 shrink-0 items-center gap-0.5 rounded-full border bg-background px-1.5 text-[10px] leading-none text-muted-foreground tabular-nums hover:bg-accent hover:text-accent-foreground"
    >
      {count}
      <Chevron className="size-3" aria-hidden />
    </button>
  )
}

import { TriangleAlertIcon } from "lucide-react"

import { cn } from "@/lib/utils"

const LABEL_FLIPS_AT = 0.7
const ROOM_BEFORE_BAR = 0.25

/**
 * One span's bar on the shared axis. `left` and `width` are fractions of the
 * track. The duration label and error badge sit right of the bar, left of it
 * near the end of the track, or inside a bar that spans most of the track, so
 * a thin bar or a full-width one stays readable.
 */
export function DurationBar({
  left,
  width,
  color,
  label,
  errors = 0,
  className,
}: {
  left: number
  width: number
  color: string
  label: string
  errors?: number
  className?: string
}) {
  const end = left + width
  const crowded = end > LABEL_FLIPS_AT
  const inside = crowded && left <= ROOM_BEFORE_BAR
  const side = !crowded
    ? { left: `calc(${end * 100}% + 4px)` }
    : inside
      ? { right: "4px" }
      : { right: `calc(${(1 - left) * 100}% + 4px)` }
  return (
    <div className={cn("relative h-full", className)}>
      <div
        data-mini="bar"
        className="absolute top-1/2 h-4 min-w-[2px] -translate-y-1/2 rounded-sm"
        style={{ left: `${left * 100}%`, width: `${width * 100}%`, backgroundColor: color }}
      />
      <span
        className="absolute top-1/2 flex -translate-y-1/2 items-center gap-1 whitespace-nowrap"
        style={side}
      >
        {errors > 0 ? (
          <span
            data-mini="error-badge"
            aria-label={errors === 1 ? "1 error" : `${errors} errors`}
            className="inline-flex h-4 items-center gap-0.5 rounded-full bg-destructive px-1.5 text-[10px] leading-none font-medium text-background tabular-nums"
          >
            <TriangleAlertIcon className="size-2.5" aria-hidden />
            {errors}
          </span>
        ) : null}
        <span
          className={cn(
            "text-[11px] tabular-nums",
            inside ? "text-background" : "text-muted-foreground"
          )}
        >
          {label}
        </span>
      </span>
    </div>
  )
}

import { useEffect, useMemo, useState, type KeyboardEvent as ReactKeyboardEvent, type ReactNode } from "react"
import { CheckIcon, CopyIcon, PinIcon, TriangleAlertIcon, XIcon } from "lucide-react"

import { Button } from "@/components/ui/button"
import { Input } from "@/components/ui/input"
import { ScrollArea } from "@/components/ui/scroll-area"

import type { Palette, Span } from "./types"
import { formatDuration, opCategory, opShares, selfTime } from "./waterfall"

const colorOf = (palette: Palette, op: string) =>
  `var(--chart-${palette.get(opCategory(op)) ?? 1})`

function Swatch({ color }: { color: string }) {
  return (
    <span
      aria-hidden
      className="size-2.5 shrink-0 rounded-sm"
      style={{ backgroundColor: color }}
    />
  )
}

function CopyButton({ text, what }: { text: string; what: string }) {
  const [copied, setCopied] = useState(false)
  useEffect(() => {
    if (!copied) return
    const timer = window.setTimeout(() => setCopied(false), 1500)
    return () => window.clearTimeout(timer)
  }, [copied])
  const copy = async () => {
    try {
      await navigator.clipboard.writeText(text)
      setCopied(true)
    } catch {
      setCopied(false)
    }
  }
  return (
    <Button
      type="button"
      variant="ghost"
      size="icon-xs"
      aria-label={copied ? `Copied ${what}` : `Copy ${what}`}
      onClick={() => void copy()}
    >
      {copied ? <CheckIcon aria-hidden /> : <CopyIcon aria-hidden />}
    </Button>
  )
}

function Chip({ children }: { children: ReactNode }) {
  return (
    <span className="inline-flex items-center gap-1.5 rounded-md border px-2 py-0.5 text-xs tabular-nums">
      {children}
    </span>
  )
}

/**
 * Read-only detail for one span: ID, errors, op and timing, description, the
 * op mix of its descendants and a searchable attribute list whose pin buttons
 * add or remove waterfall columns. Esc, or Close, calls `onClose`.
 */
export function SpanPanel({
  span,
  spans,
  palette,
  origin,
  total,
  pinnedKeys,
  onTogglePin,
  onSelectParent,
  onClose,
}: {
  span: Span
  spans: Span[]
  palette: Palette
  origin: number
  total: number
  pinnedKeys: string[]
  onTogglePin: (key: string) => void
  onSelectParent: (id: string) => void
  onClose: () => void
}) {
  const [attributeQuery, setAttributeQuery] = useState("")
  const color = colorOf(palette, span.op)
  const errors = span.errors ?? []
  const parent = span.parentId === null ? undefined : spans.find((item) => item.id === span.parentId)
  const shares = useMemo(() => opShares(spans, span.id), [spans, span.id])
  const self = useMemo(() => selfTime(spans, span.id), [spans, span.id])
  const share = total > 0 ? Math.round((Math.max(0, span.duration) / total) * 100) : 0

  const attributes = useMemo(() => {
    const needle = attributeQuery.trim().toLowerCase()
    return Object.entries(span.attributes ?? {})
      .filter(([key, value]) => !needle || `${key} ${value}`.toLowerCase().includes(needle))
      .sort(([a], [b]) => a.localeCompare(b))
  }, [span.attributes, attributeQuery])
  const attributeCount = Object.keys(span.attributes ?? {}).length

  const onKeyDown = (event: ReactKeyboardEvent<HTMLElement>) => {
    if (event.key !== "Escape") return
    event.preventDefault()
    onClose()
  }

  return (
    <aside
      aria-label="Span details"
      data-mini="panel"
      onKeyDown={onKeyDown}
      className="flex h-full min-h-0 flex-col bg-background text-sm"
    >
      <div className="flex h-9 shrink-0 items-center gap-2 border-b px-2">
        <Button type="button" variant="ghost" size="xs" onClick={onClose}>
          <XIcon aria-hidden />
          Close
        </Button>
        <span className="flex min-w-0 items-center gap-1.5 rounded-full border px-2 py-0.5 text-xs">
          <Swatch color={color} />
          <span className="truncate">
            {span.op} - {span.description}
          </span>
        </span>
      </div>
      <ScrollArea className="min-h-0 flex-1 [&_[data-slot=scroll-area-viewport]>div]:block!">
        <div className="flex flex-col gap-4 p-4 break-words">
          <div>
            <h2 className="text-base font-semibold">Span</h2>
            <div className="flex items-center gap-1 text-xs text-muted-foreground">
              <span>ID:</span>
              <code className="truncate font-[family-name:var(--mini-font-data)]">{span.id}</code>
              <CopyButton text={span.id} what="span ID" />
            </div>
          </div>

          {errors.length > 0 ? (
            <div
              role="group"
              aria-label="Errors"
              className="flex flex-col gap-1 rounded-md border border-destructive/40 bg-destructive/10 p-3 text-destructive"
            >
              <div className="flex items-center gap-1.5 text-xs font-medium">
                <TriangleAlertIcon className="size-3.5" aria-hidden />
                {errors.length === 1 ? "1 error" : `${errors.length} errors`}
              </div>
              <ul className="flex flex-col gap-0.5 text-xs">
                {errors.map((message, index) => (
                  <li key={index}>{message}</li>
                ))}
              </ul>
            </div>
          ) : null}

          <div className="flex flex-col gap-2">
            <div className="flex items-center gap-2 font-semibold">
              <Swatch color={color} />
              {span.op}
            </div>
            <div className="text-xl font-semibold tabular-nums">{formatDuration(span.duration)}</div>
            <div className="flex flex-wrap gap-1.5">
              <Chip>{share}% of trace</Chip>
              <Chip>Self time {formatDuration(self)}</Chip>
            </div>
          </div>

          <div className="flex items-start gap-1 rounded-md border bg-muted/40 p-2">
            <code className="min-w-0 flex-1 font-[family-name:var(--mini-font-data)] text-xs break-all whitespace-pre-wrap">
              {span.description}
            </code>
            <CopyButton text={span.description} what="description" />
          </div>

          {shares.length > 0 ? (
            <div className="flex flex-col gap-1.5">
              <h3 className="text-xs text-muted-foreground">Most frequent child span ops</h3>
              <div className="flex flex-wrap gap-1.5">
                {shares.map((item) => (
                  <Chip key={item.category}>
                    <Swatch
                      color={
                        palette.has(item.category)
                          ? `var(--chart-${palette.get(item.category)})`
                          : "var(--muted-foreground)"
                      }
                    />
                    {item.category} {Math.round(item.share * 100)}%
                  </Chip>
                ))}
              </div>
            </div>
          ) : null}

          <dl className="grid grid-cols-[auto_1fr] gap-x-4 gap-y-1 text-xs">
            <dt className="text-muted-foreground">Start</dt>
            <dd className="tabular-nums">{formatDuration(span.start - origin)} into the trace</dd>
            <dt className="text-muted-foreground">Parent</dt>
            <dd className="min-w-0">
              {parent ? (
                <button
                  type="button"
                  className="max-w-full truncate text-left underline-offset-2 hover:underline focus-visible:underline"
                  onClick={() => onSelectParent(parent.id)}
                >
                  {parent.op} - {parent.description}
                </button>
              ) : (
                "None"
              )}
            </dd>
          </dl>

          <section aria-label="Attributes" className="flex flex-col gap-2">
            <h3 className="text-xs font-medium">Attributes</h3>
            {attributeCount === 0 ? (
              <p className="text-xs text-muted-foreground">This span has no attributes.</p>
            ) : (
              <>
                <Input
                  value={attributeQuery}
                  onChange={(event) => setAttributeQuery(event.target.value)}
                  onKeyDown={(event) => {
                    if (event.key === "Escape" && attributeQuery) {
                      event.preventDefault()
                      event.stopPropagation()
                      setAttributeQuery("")
                    }
                  }}
                  placeholder="Search attributes"
                  aria-label="Search attributes"
                  className="h-8"
                />
                {attributes.length === 0 ? (
                  <p className="text-xs text-muted-foreground">No attributes match.</p>
                ) : (
                  <ul className="flex flex-col">
                    {attributes.map(([key, value]) => {
                      const pinned = pinnedKeys.includes(key)
                      return (
                        <li
                          key={key}
                          className="flex items-start gap-2 border-b border-border/60 py-1 text-xs last:border-b-0"
                        >
                          <span className="w-2/5 shrink-0 text-muted-foreground break-all">{key}</span>
                          <span className="min-w-0 flex-1 break-all">{value}</span>
                          <Button
                            type="button"
                            variant="ghost"
                            size="icon-xs"
                            aria-pressed={pinned}
                            aria-label={`Pin ${key} as a column`}
                            onClick={() => onTogglePin(key)}
                          >
                            <PinIcon className={pinned ? "fill-current" : undefined} aria-hidden />
                          </Button>
                        </li>
                      )
                    })}
                  </ul>
                )}
              </>
            )}
          </section>
        </div>
      </ScrollArea>
    </aside>
  )
}

import {
  Fragment,
  useEffect,
  useEffectEvent,
  useId,
  useMemo,
  useRef,
  useState,
  type KeyboardEvent as ReactKeyboardEvent,
} from "react"
import { useHotkeys } from "react-hotkeys-hook"
import { ChevronDownIcon, ChevronUpIcon, FoldHorizontalIcon, PinIcon, TriangleAlertIcon } from "lucide-react"

import { EmptyState, ErrorState, LoadingState } from "@/components/mini/states"
import { Button } from "@/components/ui/button"
import { Input } from "@/components/ui/input"
import { ResizableHandle, ResizablePanel, ResizablePanelGroup } from "@/components/ui/resizable"
import { cn } from "@/lib/utils"

import { CollapsePill } from "./collapse-pill"
import { DurationBar } from "./duration-bar"
import { SpanPanel } from "./span-panel"
import { TimeAxis, TimeGuides } from "./time-axis"
import type { Span, TreeRow, WaterfallMarker, WaterfallStat } from "./types"
import {
  ancestorIds,
  createScale,
  findGaps,
  flattenTree,
  formatDuration,
  matchSpanIds,
  opCategory,
  opPalette,
} from "./waterfall"

export type SpanWaterfallProps = {
  spans: Span[]
  status?: "loading" | "ready" | "error"
  error?: Error
  onRetry?: () => void
  title?: string
  subtitle?: string
  stats?: WaterfallStat[]
  markers?: WaterfallMarker[]
  gapThresholdMs?: number
  defaultCompressed?: boolean
  defaultPinnedKeys?: string[]
  pinnedKeys?: string[]
  onPinnedKeysChange?: (keys: string[]) => void
  selectedId?: string | null
  onSelectedIdChange?: (id: string | null) => void
  panelOpen?: boolean
  onPanelOpenChange?: (open: boolean) => void
  emptyTitle?: string
  emptyAction?: { label: string; onClick: () => void }
  "aria-label"?: string
}

const NARROW_BELOW = 560
const PINNED_WIDTH_REM = 8
const NO_SPANS: ReadonlySet<string> = new Set()

/** State that follows `value` when the parent passes one and is held locally otherwise. */
function useControllable<T>(
  value: T | undefined,
  initial: T,
  onChange?: (next: T) => void
): [T, (next: T) => void] {
  const [inner, setInner] = useState(initial)
  const controlled = value !== undefined
  const set = (next: T) => {
    if (!controlled) setInner(next)
    onChange?.(next)
  }
  return [controlled ? value : inner, set]
}

function IndentGuides({ row }: { row: TreeRow }) {
  return (
    <>
      {row.guides.map((continues, level) => {
        const elbow = level === row.depth - 1
        return (
          <span key={level} aria-hidden className="relative h-full w-4 shrink-0">
            {continues || elbow ? (
              <span
                className="absolute top-0 left-1/2 w-px bg-border"
                style={{ height: continues ? "100%" : "50%" }}
              />
            ) : null}
            {elbow ? <span className="absolute top-1/2 left-1/2 h-px w-1/2 bg-border" /> : null}
          </span>
        )
      })}
    </>
  )
}

/**
 * Tree of timed rows beside one shared time axis, with a read-only side panel
 * that squeezes the timeline. Takes data as props and never reads the store.
 * Keys act while focus is on the tree or the page body, never while typing.
 */
export function SpanWaterfall({
  spans,
  status = "ready",
  error,
  onRetry,
  title,
  subtitle,
  stats = [],
  markers,
  gapThresholdMs,
  defaultCompressed = true,
  defaultPinnedKeys,
  pinnedKeys: pinnedProp,
  onPinnedKeysChange,
  selectedId: selectedProp,
  onSelectedIdChange,
  panelOpen: panelProp,
  onPanelOpenChange,
  emptyTitle = "No spans in this trace",
  emptyAction,
  "aria-label": ariaLabel = "Trace waterfall",
}: SpanWaterfallProps) {
  const uid = useId()
  const rootRef = useRef<HTMLDivElement>(null)
  const gridRef = useRef<HTMLDivElement>(null)
  const searchRef = useRef<HTMLInputElement>(null)
  const panelWrapRef = useRef<HTMLDivElement>(null)

  const [query, setQuery] = useState("")
  const [collapsed, setCollapsed] = useState<ReadonlySet<string>>(NO_SPANS)
  const [compress, setCompress] = useState(defaultCompressed)
  const [narrow, setNarrow] = useState(false)
  const [pinned, setPinned] = useControllable<string[]>(pinnedProp, defaultPinnedKeys ?? [], onPinnedKeysChange)
  const [selectedId, setSelectedId] = useControllable<string | null>(selectedProp, null, onSelectedIdChange)
  const [panelOpen, setPanelOpen] = useControllable(panelProp, false, onPanelOpenChange)

  const ready = status === "ready"
  const rows = useMemo(() => flattenTree(spans, collapsed), [spans, collapsed])
  const fullRows = useMemo(() => flattenTree(spans, NO_SPANS), [spans])
  const scale = useMemo(
    () => createScale(spans, { gapThresholdMs, compress }),
    [spans, gapThresholdMs, compress]
  )
  const hasGaps = useMemo(() => findGaps(spans, gapThresholdMs).length > 0, [spans, gapThresholdMs])
  const palette = useMemo(() => opPalette(spans), [spans])
  const matches = useMemo(() => matchSpanIds(spans, query), [spans, query])
  const matchSet = useMemo(() => new Set(matches), [matches])
  const searching = query.trim() !== ""

  const selectedSpan = useMemo(
    () => (selectedId === null ? undefined : fullRows.find((row) => row.span.id === selectedId)?.span),
    [fullRows, selectedId]
  )
  const activeIndex = rows.findIndex((row) => row.span.id === selectedId)
  const showPanel = ready && panelOpen && selectedSpan !== undefined
  const keysOn = ready && rows.length > 0

  const rowDomId = (id: string) => `${uid}-row-${encodeURIComponent(id)}`
  const focusGrid = () => gridRef.current?.focus({ preventScroll: true })

  const errorTotal = useMemo(
    () => fullRows.reduce((sum, row) => sum + (row.span.errors?.length ?? 0), 0),
    [fullRows]
  )

  useEffect(() => {
    const element = rootRef.current
    if (!element) return
    const observer = new ResizeObserver(([entry]) => setNarrow(entry.contentRect.width < NARROW_BELOW))
    observer.observe(element)
    return () => observer.disconnect()
  }, [])

  const reconcile = useEffectEvent(() => {
    if (!ready) return
    if (selectedId !== null && selectedSpan === undefined) setSelectedId(null)
    if (panelOpen && selectedId === null) setPanelOpen(false)
  })
  useEffect(() => reconcile(), [selectedSpan, selectedId, panelOpen, ready])

  useEffect(() => {
    if (selectedId === null) return
    document.getElementById(`${uid}-row-${encodeURIComponent(selectedId)}`)?.scrollIntoView({ block: "nearest" })
  }, [selectedId, rows, uid])

  const closePanel = () => {
    const focusInPanel = panelWrapRef.current?.contains(document.activeElement)
    setPanelOpen(false)
    if (focusInPanel) focusGrid()
  }

  const select = (id: string) => {
    setSelectedId(id)
    if (document.activeElement === document.body) focusGrid()
  }

  const toggleCollapsed = (id: string) => {
    const collapsing = !collapsed.has(id)
    const next = new Set(collapsed)
    if (collapsing) next.add(id)
    else next.delete(id)
    setCollapsed(next)
    if (collapsing && selectedId !== null && ancestorIds(spans, selectedId).includes(id)) {
      setSelectedId(id)
    }
  }

  const jumpTo = (id: string) => {
    const hidden = ancestorIds(spans, id).filter((ancestor) => collapsed.has(ancestor))
    if (hidden.length > 0) {
      const next = new Set(collapsed)
      hidden.forEach((ancestor) => next.delete(ancestor))
      setCollapsed(next)
    }
    setSelectedId(id)
  }

  const stepMatch = (delta: 1 | -1) => {
    if (matches.length === 0) return
    const at = selectedId === null ? -1 : matches.indexOf(selectedId)
    const index =
      at === -1 ? (delta === 1 ? 0 : matches.length - 1) : (at + delta + matches.length) % matches.length
    jumpTo(matches[index])
  }

  const togglePin = (key: string) =>
    setPinned(pinned.includes(key) ? pinned.filter((item) => item !== key) : [...pinned, key])

  const fromTree = (event: KeyboardEvent) =>
    event.target === document.body ||
    event.target === document.documentElement ||
    event.target === gridRef.current

  const move = (to: "next" | "previous" | "first" | "last") => {
    if (rows.length === 0) return
    let index: number
    if (to === "first") index = 0
    else if (to === "last") index = rows.length - 1
    else if (activeIndex === -1) index = to === "next" ? 0 : rows.length - 1
    else index = Math.min(rows.length - 1, Math.max(0, activeIndex + (to === "next" ? 1 : -1)))
    select(rows[index].span.id)
  }

  const navigate = (event: KeyboardEvent, to: Parameters<typeof move>[0]) => {
    if (!fromTree(event)) return
    event.preventDefault()
    move(to)
  }
  useHotkeys("down", (event) => navigate(event, "next"), { enabled: keysOn })
  useHotkeys("up", (event) => navigate(event, "previous"), { enabled: keysOn })
  useHotkeys("home", (event) => navigate(event, "first"), { enabled: keysOn })
  useHotkeys("end", (event) => navigate(event, "last"), { enabled: keysOn })

  useHotkeys(
    "left",
    (event) => {
      if (!fromTree(event)) return
      event.preventDefault()
      const row = rows[activeIndex]
      if (!row) return
      if (row.expanded) toggleCollapsed(row.span.id)
      else if (row.parentId !== null) select(row.parentId)
    },
    { enabled: keysOn }
  )
  useHotkeys(
    "right",
    (event) => {
      if (!fromTree(event)) return
      event.preventDefault()
      const row = rows[activeIndex]
      if (!row) return
      if (row.childCount > 0 && !row.expanded) toggleCollapsed(row.span.id)
      else if (row.expanded) select(rows[activeIndex + 1].span.id)
    },
    { enabled: keysOn }
  )
  useHotkeys(
    "enter",
    (event) => {
      if (!fromTree(event) || selectedSpan === undefined) return
      event.preventDefault()
      setPanelOpen(true)
    },
    { enabled: keysOn }
  )
  useHotkeys(
    "esc",
    (event) => {
      if (!fromTree(event)) return
      event.preventDefault()
      closePanel()
    },
    { enabled: ready && panelOpen }
  )

  const onSearchKeyDown = (event: ReactKeyboardEvent<HTMLInputElement>) => {
    if (event.key === "Enter") {
      event.preventDefault()
      stepMatch(event.shiftKey ? -1 : 1)
    } else if (event.key === "Escape") {
      event.preventDefault()
      if (query) setQuery("")
      else {
        event.currentTarget.blur()
        focusGrid()
      }
    } else if (event.key === "ArrowDown") {
      event.preventDefault()
      if (selectedId === null && rows.length > 0) setSelectedId(rows[0].span.id)
      focusGrid()
    }
  }

  const matchText = !searching
    ? ""
    : matches.length === 0
      ? "No matches"
      : selectedId !== null && matches.includes(selectedId)
        ? `${matches.indexOf(selectedId) + 1} of ${matches.length}`
        : `${matches.length} ${matches.length === 1 ? "match" : "matches"}`

  const columns = ["minmax(11rem, 36%)", ...pinned.map(() => `${PINNED_WIDTH_REM}rem`), "minmax(10rem, 1fr)"].join(" ")
  const minWidth = `calc(21rem + ${pinned.length * PINNED_WIDTH_REM}rem)`

  let body
  if (status === "loading") {
    body = <LoadingState label="Loading trace" />
  } else if (status === "error") {
    body = <ErrorState error={error ?? new Error("Unknown error")} onRetry={onRetry} />
  } else if (spans.length === 0) {
    body = (
      <EmptyState
        title={emptyTitle}
        description="Spans will show up here once the run reports them."
        action={
          emptyAction ? (
            <Button variant="outline" size="sm" onClick={emptyAction.onClick}>
              {emptyAction.label}
            </Button>
          ) : undefined
        }
      />
    )
  } else {
    body = (
      <div
        ref={gridRef}
        role="treegrid"
        tabIndex={0}
        aria-label={ariaLabel}
